 "content": "def transform(grid):
    """Restore the original 180-degree-symmetric picture beneath color-2 mask."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each masked location is paired with its rotational counterpart. If both
    # members are masked, recover that pair from the symmetric pattern around it.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and grid[h - 1 - r][w - 1 - c] != 2:
                out[r][c] = grid[h - 1 - r][w - 1 - c]
    # For a fully covered symmetric pair, the revealed design itself repeats
    # by 180 degrees in its 24x24 tiling, so use the pattern at the same offset
    # in the nearest visible repeated tile. (The mask is centered; tiles have
    # period 24 around the outside reflected frame.)
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                rr, cc = h - 1 - r, w - 1 - c
                if grid[rr][cc] == 2:
                    # Reflect across the centerline only, then use whichever
                    # corresponding cell remains visible.
                    for r2, c2 in ((r, w-1-c), (h-1-r, c)):
                        if grid[r2][c2] != 2:
                            out[r][c] = grid[r2][c2]
                            break
    return out

